'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import type { ChangeEvent } from 'react';
import { useRouter } from 'next/navigation';
import type { SessionUser } from '@/lib/auth';
import { RoomsEditor, ChargesEditor, TasksSection, GuestsSection, ExpensesSection, RulesSection, money, dateAR, jsonBody, type Room } from './sections';
import { ResidentRentHistory, type HistoryPayment } from './rent-history';
import { FinanceSection } from './finance';
import { RentSettingsCard } from './rent-settings';
import { HomesSection, InvitesCard, InstallCard, PushToggle, DeleteAccount, FeedbackCard, roleLabel, type Membership } from './app-features';

type Notice={id:string;title:string;description:string;category:string;priority:string;status:string;created_at:string;author_id:string;photo_url?:string|null};
type Payment={id:string;cancelled?:boolean;cancel_reason?:string|null;manual?:boolean;reported_at?:string|null;resident_id:string;due_date:string;amount:number;services_amount:number;services_detail:{name:string;amount:number}[];total:number;overdue:boolean;room:string|null;paid:boolean;paid_at:string|null;proof_path?:string|null;proof_url?:string|null;proof_uploaded_at?:string|null;users?:{name:string;username:string;room:string|null;email?:string|null}};
type RentMeta={history:HistoryPayment[];history_from:string;due_date:string;next_due:string;paid_total:number;pending_total:number;overdue_total:number};
type Laundry={id:string;date:string;start_time:string;end_time:string;user_id:string;finished:boolean;users?:{name:string;username:string;room:string|null}|null};
type User={id:string;name:string;username:string;role:string;room:string|null;email:string|null;phone:string|null;emergency_phone:string|null;active:boolean;created_at:string;photo_path?:string|null;password?:string};
type Notif={id:string;title:string;message:string;kind:string;read:boolean;created_at:string};
type Profile=User&{photo_url?:string|null;login_email?:string|null;home_name?:string|null};
type Guest={id:string;guest_name:string;visit_date:string;start_time:string;users?:{name:string}|null};

const iconMap:Record<string,string>={inicio:'🏠',avisos:'📣',lavarropas:'🧺',calendario:'📅',alquiler:'💰',habitantes:'👥',tareas:'🧹',invitados:'🙋',gastos:'🧾',finanzas:'📊',perfil:'🧑',notificaciones:'🔔',normas:'📜',residencias:'🏘️'};
const title:Record<string,string>={residencias:'Mis residencias',inicio:'Inicio',avisos:'Avisos','nuevo-aviso':'Nuevo aviso',lavarropas:'Lavarropas',calendario:'Calendario',alquiler:'Alquiler',habitantes:'Habitantes',tareas:'Tareas del mes',invitados:'Invitados',gastos:'Gastos',finanzas:'Finanzas',normas:'Normas de convivencia',notificaciones:'Notificaciones',perfil:'Mi perfil'};
const subtitle:Record<string,string>={residencias:'Cambiá de residencia, creá una nueva o unite con un código.',avisos:'Lo que pasa en la casa.','nuevo-aviso':'Le llega a todos como notificación.',lavarropas:'Reservá tu turno sin pisarte con nadie.',calendario:'Lavarropas, visitas y vencimientos.',alquiler:'Pagos del mes y deudas anteriores.',habitantes:'Habitaciones, cupos y personas.',tareas:'Quién hace qué, día por día.',invitados:'Quién viene y cuándo.',gastos:'Todo lo que se compra o arregla.',finanzas:'Pagos, ingresos, gastos y ganancia.',normas:'Para convivir bien.',notificaciones:'Todo lo que te llegó.',perfil:'Tus datos y tu contraseña.'};
const notifIcon:Record<string,string>={rent:'💰',notice:'📣',task:'🧹',guest:'🙋',general:'🔔'};

function beep(){try{const AC=window.AudioContext||(window as any).webkitAudioContext;const c=new AC();const o=c.createOscillator();const g=c.createGain();o.frequency.value=880;g.gain.setValueAtTime(.001,c.currentTime);g.gain.exponentialRampToValueAtTime(.12,c.currentTime+.02);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.22);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.23);}catch{}}
const localKey=(d:Date)=>d.toLocaleDateString('en-CA');
const tabFromUrl=()=>typeof window==='undefined'?'inicio':new URLSearchParams(window.location.search).get('s')||'inicio';

export default function Dashboard({session}:{session:SessionUser}){
 const router=useRouter();
 // "isOwner" incluye a encargados: tienen los mismos permisos de gestión dentro de la residencia.
 const isOwner=session.role!=='resident';
 const tabs=isOwner?['inicio','avisos','alquiler','habitantes','tareas','finanzas','invitados','lavarropas','calendario','normas','notificaciones','perfil','residencias']:['inicio','avisos','alquiler','tareas','invitados','lavarropas','calendario','normas','notificaciones','perfil'];
 const [tab,setTab]=useState('inicio'); const [moreOpen,setMoreOpen]=useState(false);
 const [notices,setNotices]=useState<Notice[]>([]); const [payments,setPayments]=useState<Payment[]>([]); const [rentMeta,setRentMeta]=useState<RentMeta|null>(null); const [laundry,setLaundry]=useState<Laundry[]>([]); const [users,setUsers]=useState<User[]>([]); const [rooms,setRooms]=useState<Room[]>([]); const [guests,setGuests]=useState<Guest[]>([]); const [notifications,setNotifications]=useState<Notif[]>([]); const [profile,setProfile]=useState<Profile|null>(null);
 const [toast,setToast]=useState(''); const [loading,setLoading]=useState(true); const [editingNotice,setEditingNotice]=useState<Notice|null>(null); const [editingLaundry,setEditingLaundry]=useState<Laundry|null>(null); const [editingUser,setEditingUser]=useState<User|null>(null); const [month,setMonth]=useState(new Date()); const [editingPayment,setEditingPayment]=useState<{id:string;name:string;due:string;amount:string;services_amount:string;manual:boolean}|null>(null);
 const [noticeForm,setNoticeForm]=useState({title:'',description:'',category:'Plomería',priority:'Media'});
 const [noticeFile,setNoticeFile]=useState<File|null>(null); const [editNoticeFile,setEditNoticeFile]=useState<File|null>(null); const [fileKey,setFileKey]=useState(0);
 const [laundryForm,setLaundryForm]=useState({date:localKey(new Date()),start_time:'18:00',end_time:'20:00'});
 const emptyUser={name:'',username:'',password:'',room:'',email:'',phone:'',emergency_phone:''};
 const [userForm,setUserForm]=useState(emptyUser);
 const [profileForm,setProfileForm]=useState({name:'',email:'',phone:'',emergency_phone:''});
 const [passwordForm,setPasswordForm]=useState({current_password:'',new_password:'',confirm:''});
 const [notifForm,setNotifForm]=useState({user_id:'',message:'',title:'Aviso del dueño'});
 const [busy,setBusy]=useState<string|null>(null);
 const [homes,setHomes]=useState<Membership[]>([]); const [homesOpen,setHomesOpen]=useState(false); const [hideInstall,setHideInstall]=useState(true);
 const firstNotifications=useRef(true);
 const lastNotifIds=useRef<string[]>([]);

 // Cada sección tiene su propia URL (?s=alquiler): el botón "atrás" vuelve a la sección anterior y se puede compartir el link.
 function go(t:string){setTab(t);setMoreOpen(false);if(tabFromUrl()!==t)window.history.pushState(null,'',t==='inicio'?'/dashboard':`/dashboard?s=${t}`);window.scrollTo({top:0});}
 useEffect(()=>{const sync=()=>setTab(tabFromUrl());sync();window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync)},[]);

 async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const j=await r.json();if(r.status===401){router.push('/login');throw new Error('Tu sesión terminó.')}if(!r.ok)throw new Error(j.error||'Error');return j;}
 function applyNotifications(items:Notif[]){if(!firstNotifications.current&&items.some(n=>!lastNotifIds.current.includes(n.id)))beep();lastNotifIds.current=items.map(n=>n.id);firstNotifications.current=false;setNotifications(items);}
 async function loadRent(){const p=await api('/api/rent');setPayments(p.items||[]);setRentMeta(p);}
 async function loadRooms(){setRooms((await api('/api/rooms')).items||[]);}
 async function load(silent=false){if(!silent)setLoading(true);try{const [n,l,pr,no,g]=await Promise.all([api('/api/notices'),api('/api/laundry'),api('/api/profile'),api('/api/notifications'),api('/api/guests'),loadRent(),loadRooms()]);setNotices(n.items||[]);setLaundry(l.items||[]);setProfile(pr.user);setGuests(g.items||[]);if(isOwner){const u=await api('/api/users');setUsers(u.items||[]);}api('/api/homes').then(h=>setHomes(h.items||[])).catch(()=>{});applyNotifications(no.items||[]);}catch(e){show(e instanceof Error?e.message:'Error')}finally{if(!silent)setLoading(false)}}
 // Las notificaciones se consultan cada 12 s (para el sonido); el resto se refresca cada minuto.
 useEffect(()=>{load();const fast=setInterval(()=>api('/api/notifications').then(j=>applyNotifications(j.items||[])).catch(()=>{}),12000);const slow=setInterval(()=>load(true),60000);return()=>{clearInterval(fast);clearInterval(slow)}},[]);
 // Cambia de residencia: el servidor actualiza la sesión y se recarga todo con los datos de la otra casa.
 async function switchHome(memberId:string){try{await api('/api/homes',jsonBody('POST',{action:'switch',member_id:memberId}));window.location.href='/dashboard'}catch(e){show(errMsg(e))}}
 // Un link de notificación push puede traer ?m=<membresía> de otra residencia de la misma cuenta.
 useEffect(()=>{const m=new URLSearchParams(window.location.search).get('m');if(m&&m!==session.id)api('/api/homes',jsonBody('POST',{action:'switch',member_id:m})).then(()=>window.location.replace(window.location.pathname+'?s=notificaciones')).catch(()=>{});try{setHideInstall(localStorage.getItem('nidapp-hide-install')==='1')}catch{setHideInstall(false)}},[]);
 function show(s:string){setToast(s);setTimeout(()=>setToast(''),3000)}
 const errMsg=(e:unknown)=>e instanceof Error?e.message:'Error';
 // Evita dobles clics: mientras una acción con la misma clave está en curso, se ignora.
 async function once(key:string,fn:()=>Promise<void>){if(busy===key)return;setBusy(key);try{await fn()}finally{setBusy(null)}}
 async function logout(){await fetch('/api/auth/logout',{method:'POST'});router.push('/login')}
 async function createNotice(){if(!noticeForm.title||!noticeForm.description)return show('Completá título y descripción.');await once('notice',async()=>{try{const photo_path=noticeFile?(await upload(noticeFile,'notice')).path:undefined;await api('/api/notices',jsonBody('POST',{...noticeForm,photo_path}));setNoticeForm({title:'',description:'',category:'Plomería',priority:'Media'});setNoticeFile(null);setFileKey(k=>k+1);show('Aviso publicado y notificado a todos 🎉');await load(true);go('avisos')}catch(e){show(errMsg(e))}})}
 async function saveNotice(){if(!editingNotice)return;try{const {photo_url,...rest}=editingNotice as Notice&{remove_photo?:boolean};const body:any={...rest};if(editNoticeFile)body.photo_path=(await upload(editNoticeFile,'notice')).path;else if((editingNotice as any).remove_photo)body.photo_path=null;delete body.remove_photo;await api('/api/notices',jsonBody('PATCH',body));setEditingNotice(null);setEditNoticeFile(null);show('Aviso actualizado ✅');await load(true)}catch(e){show(errMsg(e))}}
 async function deleteNotice(id:string){if(!confirm('¿Eliminar este aviso?'))return;try{await api('/api/notices',jsonBody('DELETE',{id}));show('Aviso eliminado');await load(true)}catch(e){show(errMsg(e))}}
 async function reserve(){await once('laundry',async()=>{try{await api('/api/laundry',jsonBody('POST',laundryForm));show('Lavarropas reservado 🧺');await load(true)}catch(e){show(errMsg(e))}})}
 async function saveLaundry(){if(!editingLaundry)return;try{await api('/api/laundry',jsonBody('PATCH',editingLaundry));setEditingLaundry(null);show('Reserva modificada');await load(true)}catch(e){show(errMsg(e))}}
 async function finishLaundry(l:Laundry){try{await api('/api/laundry',jsonBody('PATCH',{id:l.id,finished:true}));show('Reserva marcada como finalizada ✅');await load(true)}catch(e){show(errMsg(e))}}
 async function cancelLaundry(l:Laundry){if(!confirm('¿Cancelar esta reserva?'))return;try{await api('/api/laundry',jsonBody('DELETE',{id:l.id}));show('Reserva cancelada');await load(true)}catch(e){show(errMsg(e))}}
 async function togglePaid(p:Payment){await once('paid-'+p.id,async()=>{try{await api('/api/rent',jsonBody('PATCH',{id:p.id,paid:!p.paid}));show(p.paid?'Pago marcado como pendiente':'Pago registrado ✅');await loadRent()}catch(e){show(errMsg(e))}})}
 async function remind(p:Payment){await once('remind-'+p.id,async()=>{try{await api('/api/rent/remind',jsonBody('POST',{id:p.id}));show('Recordatorio enviado 🔔')}catch(e){show(errMsg(e))}})}
 async function savePayment(){if(!editingPayment)return;await once('pay-edit',async()=>{try{await api('/api/rent',jsonBody('PATCH',{id:editingPayment.id,amount:Number(editingPayment.amount),services_amount:Number(editingPayment.services_amount)}));setEditingPayment(null);show('Pago actualizado ✅');await loadRent()}catch(e){show(errMsg(e))}})}
 async function resetPayment(){if(!editingPayment)return;try{await api('/api/rent',jsonBody('PATCH',{id:editingPayment.id,manual:false}));setEditingPayment(null);show('Monto recalculado automáticamente');await loadRent()}catch(e){show(errMsg(e))}}
 async function cancelPayment(p:Payment){const reason=prompt(`Anular el cobro de ${p.users?.name||'este habitante'} (vence ${dateAR(p.due_date)}).\nQueda en el registro como "anulado" y lo podés restaurar.\n\nMotivo (opcional):`,'');if(reason===null)return;try{await api('/api/rent',jsonBody('DELETE',{id:p.id,reason}));if(editingPayment?.id===p.id)setEditingPayment(null);show('Cobro anulado. Lo ves en el Registro de pagos.');await loadRent()}catch(e){show(errMsg(e))}}
 async function remindAll(){const target=rentMeta?.next_due||due;const mName=target?new Date(target+'T12:00:00').toLocaleDateString('es-AR',{month:'long'}):'el mes';if(!confirm(`¿Avisar a todos los habitantes que ya pueden pagar el alquiler de ${mName}?`))return;await once('remind-all',async()=>{try{const j=await api('/api/rent/remind-all',{method:'POST'});show(j.sent?`Aviso enviado a ${j.sent} persona${j.sent===1?'':'s'} 📢`:`Nadie para avisar: todos pagaron ${mName} o ya recibieron el aviso hoy.`)}catch(e){show(errMsg(e))}})}
 async function deleteNotif(n?:Notif){try{await api('/api/notifications',jsonBody('DELETE',n?{id:n.id}:{read:true}));setNotifications(notifications.filter(x=>n?x.id!==n.id:!x.read));show(n?'Notificación borrada':'Notificaciones leídas borradas 🧹')}catch(e){show(errMsg(e))}}
 async function sendNotification(){await once('notif',async()=>{try{await api('/api/notifications',jsonBody('POST',notifForm));setNotifForm(x=>({...x,message:''}));show('Notificación enviada 🔔')}catch(e){show(errMsg(e))}})}
 async function createUser(){await once('user',async()=>{try{await api('/api/users',jsonBody('POST',userForm));setUserForm(emptyUser);show('Habitante creado 👋 Pasale su usuario y contraseña.');await Promise.all([load(true)])}catch(e){show(errMsg(e))}})}
 async function saveUser(){if(!editingUser)return;try{await api('/api/users',jsonBody('PATCH',editingUser));setEditingUser(null);show('Datos del habitante actualizados');await load(true)}catch(e){show(errMsg(e))}}
 async function setUserActive(u:User,active:boolean){if(!active&&!confirm(`¿Desactivar a ${u.name}? Ya no va a poder entrar a NIDAPP.`))return;try{await api('/api/users',active?jsonBody('PATCH',{id:u.id,active:true,room:u.room}):jsonBody('DELETE',{id:u.id}));show(active?'Habitante reactivado':'Habitante desactivado');await load(true)}catch(e){show(errMsg(e))}}
 async function saveProfile(){try{const j=await api('/api/profile',jsonBody('PATCH',profileForm));setProfile(j.user);show('Perfil actualizado ✅')}catch(e){show(errMsg(e))}}
 async function changePassword(){if(passwordForm.new_password!==passwordForm.confirm)return show('Las contraseñas nuevas no coinciden.');try{await api('/api/profile',jsonBody('PATCH',{current_password:passwordForm.current_password,new_password:passwordForm.new_password}));setPasswordForm({current_password:'',new_password:'',confirm:''});show('Contraseña cambiada 🔐')}catch(e){show(errMsg(e))}}
 async function upload(file:File,kind:'photo'|'proof'|'guest'|'notice'){const fd=new FormData();fd.append('file',file);fd.append('kind',kind);return api('/api/files',{method:'POST',body:fd})}
 async function uploadPhoto(e:ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;try{const j=await upload(f,'photo');const r=await api('/api/profile',jsonBody('PATCH',{photo_path:j.path}));setProfile(r.user);show('Foto actualizada 📸')}catch(e){show(errMsg(e))}}
 async function uploadProof(e:ChangeEvent<HTMLInputElement>,p:Payment){const f=e.target.files?.[0];if(!f)return;try{const j=await upload(f,'proof');await api('/api/rent',jsonBody('PATCH',{id:p.id,proof_path:j.path}));show('Comprobante enviado al dueño 📎');await loadRent()}catch(e){show(errMsg(e))}}
 async function reportPaid(p:Payment){await once('report-'+p.id,async()=>{try{await api('/api/rent',jsonBody('PATCH',{id:p.id,report:true}));show('Le avisamos al dueño que pagaste 💸');await loadRent()}catch(e){show(errMsg(e))}})}
 async function markRead(n?:Notif){try{await api('/api/notifications',jsonBody('PATCH',n?{id:n.id}:{all:true}));setNotifications(notifications.map(x=>!n||x.id===n.id?{...x,read:true}:x))}catch(e){show(errMsg(e))}}

 const unread=notifications.filter(n=>!n.read).length;
 const due=rentMeta?.due_date;
 const currentPayments=payments.filter(p=>p.due_date===due); const overduePayments=payments.filter(p=>p.due_date!==due);
 const paidCount=currentPayments.filter(p=>p.paid).length; const myUnpaid=payments.filter(p=>!p.paid);
 const overdueCount=payments.filter(p=>!p.paid&&p.overdue).length;
 const badge=unread?`🔔 ${unread} nueva${unread===1?'':'s'}`:isOwner?(overdueCount?`⚠️ ${overdueCount} pago${overdueCount===1?'':'s'} vencido${overdueCount===1?'':'s'}`:currentPayments.length-paidCount?`💰 ${currentPayments.length-paidCount} pago${currentPayments.length-paidCount===1?'':'s'} pendiente${currentPayments.length-paidCount===1?'':'s'}`:'✨ Todo al día'):(myUnpaid.some(p=>p.overdue)?'⚠️ Alquiler vencido':myUnpaid.length?'💰 Pago pendiente':'✨ Todo al día');
 const roomsGrouped=useMemo(()=>rooms.map(r=>({...r,people:users.filter(u=>u.role==='resident'&&u.room===r.number&&u.active)})),[users,rooms]);
 const inactive=users.filter(u=>u.role==='resident'&&!u.active);
 const calendarDays=useMemo(()=>{const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate();return Array.from({length:42},(_,i)=>{const d=i-start+1;return d>0&&d<=days?new Date(y,m,d):null})},[month]);
 const eventsFor=(d:Date)=>{const key=localKey(d);return [...(due===key?[{id:'rent',text:'💰 Vence alquiler'}]:[]),...laundry.filter(l=>l.date===key&&!l.finished).map(l=>({id:l.id,text:`🧺 ${l.start_time.slice(0,5)} · ${l.users?.name||'Reserva'}`})),...guests.filter(g=>g.visit_date===key).map(g=>({id:g.id,text:`🙋 ${g.start_time.slice(0,5)} · ${g.guest_name}`}))]};
 const todayKey=localKey(new Date());
 useEffect(()=>{if(tab==='perfil'&&profile)setProfileForm({name:profile.name,email:profile.login_email||profile.email||'',phone:profile.phone||'',emergency_phone:profile.emergency_phone||''})},[tab,profile]);
 useEffect(()=>{if(isOwner)setNotifForm(x=>({...x,user_id:x.user_id||users.find(u=>u.role==='resident'&&u.active)?.id||''}))},[users,isOwner]);
 useEffect(()=>{if(!userForm.room){const free=rooms.find(r=>r.occupants<r.capacity);if(free)setUserForm(f=>({...f,room:free.number}))}},[rooms]);
 const roomOptions=(current?:string|null)=>rooms.map(r=><option key={r.id} value={r.number} disabled={r.occupants>=r.capacity&&r.number!==current}>Hab. {r.number} ({r.occupants}/{r.capacity}){r.occupants>=r.capacity&&r.number!==current?' · completa':''}</option>);

 const paymentRow=(p:Payment)=><tr key={p.id} className={p.overdue?'row-overdue':''}><td className="cell-head"><div className="person"><div className="avatar">🧑</div><div>{p.users?.name}<br/><span className="muted">Hab. {p.room||p.users?.room||'—'}</span></div></div></td><td data-label="VENCE">{dateAR(p.due_date)}</td><td data-label="ALQUILER">{money(p.amount)}</td><td data-label="SERVICIOS" title={p.services_detail?.map(s=>`${s.name}: ${money(s.amount)}`).join('\n')}>{money(p.services_amount)}</td><td data-label="TOTAL"><b>{money(p.total)}</b>{p.manual&&<div className="mini muted">editado</div>}</td><td data-label="ESTADO"><span className={'status '+(p.paid?'paid':p.overdue?'pending':'due')}>{p.paid?'PAGÓ ✅':p.overdue?'VENCIDO !':'PENDIENTE'}</span>{!p.paid&&p.reported_at&&<div className="tag green" title={`Avisó el ${new Date(p.reported_at).toLocaleString('es-AR')}`}>💸 Avisó que pagó</div>}</td><td data-label="COMPROBANTE">{p.proof_url?<a href={p.proof_url} target="_blank" rel="noreferrer" className="button blue">Ver</a>:<span className="muted mini">—</span>}</td><td className="cell-actions"><div className="row-actions pay-actions"><button className={'button main-action '+(p.paid?'red':'')} disabled={busy==='paid-'+p.id} onClick={()=>togglePaid(p)}>{p.paid?'Marcar deuda':'Confirmar pago'}</button>{!p.paid?<button className="button yellow icon-only" disabled={busy==='remind-'+p.id} onClick={()=>remind(p)} aria-label={`Enviar recordatorio a ${p.users?.name}`} title="Enviar recordatorio">🔔</button>:<a className="button icon-only" href={`/recibo?id=${p.id}`} target="_blank" rel="noreferrer" aria-label={`Recibo de ${p.users?.name}`} title="Ver recibo (PDF)">🧾</a>}<button className="button blue icon-only" onClick={()=>setEditingPayment({id:p.id,name:p.users?.name||'Habitante',due:p.due_date,amount:String(p.amount),services_amount:String(p.services_amount),manual:Boolean(p.manual)})} aria-label={`Editar el cobro de ${p.users?.name}`} title="Editar montos">✏️</button><button className="button red icon-only" onClick={()=>cancelPayment(p)} aria-label={`Anular el cobro de ${p.users?.name}`} title="Anular cobro (queda en el registro)">⊘</button></div></td></tr>;

 return <div className="shell"><header className="topbar"><div className="brand"><img className="brand-mark" src="/icons/icon-192.png" alt="NIDAPP"/><div><div className="brand-title pixel">NIDAPP</div><div className="brand-sub">{session.home_name||'Tu residencia, organizada.'}</div></div></div>{(isOwner||homes.length>1)&&<div className="home-switch"><button className="home-btn" onClick={()=>setHomesOpen(o=>!o)} aria-expanded={homesOpen} aria-label="Cambiar de residencia">🏠 <span className="home-btn-name">{session.home_name||'Residencia'}</span>{homes.some(h=>h.member_id!==session.id&&h.unread)?<b className="nav-count">{homes.filter(h=>h.member_id!==session.id).reduce((a,h)=>a+h.unread,0)}</b>:null} ▾</button>{homesOpen&&<div className="home-menu" role="menu">{homes.map(h=><button key={h.member_id} role="menuitem" className={h.member_id===session.id?'current':''} onClick={()=>h.member_id===session.id?setHomesOpen(false):switchHome(h.member_id)}><b>{h.name}</b><span className="mini muted">{roleLabel(h.role)}{h.unread?` · 🔔 ${h.unread}`:''}{h.member_id===session.id?' · actual':''}</span></button>)}{isOwner&&<button role="menuitem" onClick={()=>{setHomesOpen(false);go('residencias')}}><b>➕ Nueva residencia o código</b></button>}</div>}</div>}<div className="user-chip"><button className="avatar-btn" onClick={()=>go('perfil')} aria-label="Mi perfil"><div className="avatar">{profile?.photo_url?<img src={profile.photo_url} alt={`Foto de ${profile.name}`} style={{width:'100%',height:'100%',objectFit:'cover'}}/>:(isOwner?'👑':'🧑')}</div></button><div className="mini"><b>{profile?.name||session.name}</b><br/><span className="muted">{roleLabel(session.role)}{!isOwner&&profile?.room?` · Hab. ${profile.room}`:''}</span></div><button className="logout" onClick={logout} aria-label="Salir"><span aria-hidden>🚪</span><span className="logout-text">Salir</span></button></div></header>
 <main className="layout"><aside className="sidebar"><nav className="navcard" aria-label="Secciones">{tabs.map(t=><button key={t} className={'navitem '+(tab===t?'active':'')} aria-current={tab===t?'page':undefined} onClick={()=>go(t)}><span className="navico">{iconMap[t]}</span>{title[t]}{t==='notificaciones'&&unread>0?<span className="tag red" style={{marginLeft:'auto',marginTop:0}}>{unread}</span>:null}</button>)}</nav><div className="navnote">💡 <b>Tip:</b> las notificaciones nuevas tienen sonido. En el navegador, hacé al menos un clic/tap para habilitar audio.</div></aside>
 <section className="content"><div className="hero"><div><h1 className="pixel">{title[tab]||'Inicio'}</h1><p>{tab==='inicio'?(isOwner?'Panel del dueño.':'Panel del habitante · todo lo que necesitás, a mano.'):subtitle[tab]}</p></div><button className="hero-badge" onClick={()=>go(unread?'notificaciones':'alquiler')}>{badge}</button></div>
 {loading?<div className="card empty">Cargando NIDAPP...</div>:<>
 {tab==='inicio'&&!hideInstall&&<InstallCard compact onDismiss={()=>{setHideInstall(true);try{localStorage.setItem('nidapp-hide-install','1')}catch{}}}/>}
 {tab==='inicio'&&<div className="grid"><div className="card span-8"><h3 className="card-title"><span>📣 Avisos importantes</span><button className="button pink" onClick={()=>go('avisos')}>Ver avisos</button></h3>{notices.slice(0,3).map(n=><div className={'notice '+(n.priority==='Alta'?'red':n.priority==='Baja'?'green':'yellow')} key={n.id}><div className="notice-icon">{n.category==='Plomería'?'🚰':'📌'}</div><div className="notice-main"><div className="notice-title">{n.title}</div><div className="mini muted">{n.description}</div><span className={'tag '+(n.status==='Resuelto'?'green':n.priority==='Alta'?'red':'yellow')}>{n.status}</span></div></div>)}{!notices.length&&<div className="empty">Todavía no hay avisos.</div>}</div>
 <div className="card span-4"><h3 className="card-title"><span>💰 Alquiler</span></h3>{isOwner?<><div className="big-number">{money(rentMeta?.paid_total||0)}</div><div className="mini">cobrado este mes</div><b>{money(rentMeta?.pending_total||0)} pendientes</b>{(rentMeta?.overdue_total||0)>0&&<div className="tag red">⚠️ {money(rentMeta!.overdue_total)} vencidos</div>}</>:<><div className="big-number">{money(myUnpaid.reduce((a,p)=>a+p.total,0))}</div><div className="mini">{myUnpaid.length?'a pagar (alquiler + servicios)':'nada pendiente'}</div><b>{myUnpaid.some(p=>p.overdue)?'⚠️ Tenés un pago vencido':myUnpaid.length?`Vence el ${dateAR(myUnpaid[0].due_date)}`:'Pago al día ✅'}</b>{!myUnpaid.length&&rentMeta?.next_due&&<div className="mini muted">Próximo vencimiento: {dateAR(rentMeta.next_due)}</div>}</>}<button className="button yellow" style={{width:'100%',marginTop:10}} onClick={()=>go('alquiler')}>Ver alquiler</button></div>
 <div className="card span-4"><h3 className="card-title"><span>🧺 Próxima reserva</span></h3>{laundry.find(l=>!l.finished)?(()=>{const l=laundry.find(x=>!x.finished)!;return <><div className="big-number">{l.start_time.slice(0,5)}</div><div className="mini">{dateAR(l.date)} · {l.users?.name||'Habitante'}</div></>})():<div className="empty">Sin reservas</div>}<button className="button blue" style={{width:'100%',marginTop:10}} onClick={()=>go('lavarropas')}>Abrir lavarropas</button></div>
 <div className="card span-8"><h3 className="card-title"><span>⚡ Accesos rápidos</span></h3><div className="quickgrid">{tabs.filter(t=>!['inicio','notificaciones','perfil'].includes(t)).map((t,i)=><button className={'quick '+['pink','blue','yellow','green','purple','orange'][i%6]} key={t} onClick={()=>go(t)}><span>{iconMap[t]}</span>{title[t]}</button>)}</div></div><FeedbackCard api={api} show={show}/></div>}

 {tab==='avisos'&&<div className="grid"><div className="card span-12"><h3 className="card-title"><span>📣 Avisos de la residencia</span><button className="button pink" onClick={()=>go('nuevo-aviso')}>+ Nuevo aviso</button></h3>{notices.map(n=><div className={'notice '+(n.priority==='Alta'?'red':n.priority==='Baja'?'green':'yellow')} key={n.id}><div className="notice-icon">{n.category==='Plomería'?'🚰':'📌'}</div><div className="notice-main"><div className="notice-title">{n.title}</div><div className="mini muted">{n.description}</div>{n.photo_url&&<a href={n.photo_url} target="_blank" rel="noreferrer" className="notice-photo"><img src={n.photo_url} alt={`Foto del aviso: ${n.title}`}/></a>}<span className="tag">{n.priority}</span> <span className="mini muted">{new Date(n.created_at).toLocaleDateString('es-AR')}</span></div><span className="status due">{n.status}</span>{(isOwner||n.author_id===session.id)&&<button className="button blue" onClick={()=>setEditingNotice({...n})}>Modificar</button>}{isOwner&&<button className="button red" onClick={()=>deleteNotice(n.id)}>Eliminar</button>}</div>)}{!notices.length&&<div className="empty">No hay avisos.</div>}
 {editingNotice&&<div className="card" style={{marginTop:12,background:'#f3ecff'}}><h3 className="card-title">✏️ Modificar aviso</h3><div className="form"><div className="field"><label htmlFor="en-title">TÍTULO</label><input id="en-title" value={editingNotice.title} onChange={e=>setEditingNotice({...editingNotice,title:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="en-cat">CATEGORÍA</label><select id="en-cat" value={editingNotice.category} onChange={e=>setEditingNotice({...editingNotice,category:e.target.value})}><option>Plomería</option><option>Electricidad</option><option>Limpieza</option><option>General</option></select></div><div className="field"><label htmlFor="en-prio">PRIORIDAD</label><select id="en-prio" value={editingNotice.priority} onChange={e=>setEditingNotice({...editingNotice,priority:e.target.value})}><option>Baja</option><option>Media</option><option>Alta</option></select></div></div><div className="field"><label htmlFor="en-desc">DESCRIPCIÓN</label><textarea id="en-desc" value={editingNotice.description} onChange={e=>setEditingNotice({...editingNotice,description:e.target.value})}/></div><div className="field"><label htmlFor="en-photo">{editingNotice.photo_url?'CAMBIAR FOTO':'AGREGAR FOTO'}</label><input id="en-photo" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setEditNoticeFile(e.target.files?.[0]||null)}/>{editingNotice.photo_url&&<label className="mini"><input type="checkbox" checked={Boolean((editingNotice as any).remove_photo)} onChange={e=>setEditingNotice({...editingNotice,remove_photo:e.target.checked} as any)}/> Quitar la foto actual</label>}</div>{isOwner&&<div className="field"><label htmlFor="en-status">ESTADO DEL AVISO</label><select id="en-status" value={editingNotice.status} onChange={e=>setEditingNotice({...editingNotice,status:e.target.value})}><option>Pendiente</option><option>En progreso</option><option>Resuelto</option></select></div>}<div style={{display:'flex',gap:8}}><button className="button" onClick={saveNotice}>GUARDAR</button><button className="button red" onClick={()=>setEditingNotice(null)}>CANCELAR</button></div></div></div>}</div></div>}
 {tab==='nuevo-aviso'&&<div className="grid"><div className="card span-8"><h3 className="card-title">📣 Nuevo aviso</h3><div className="form"><div className="field"><label htmlFor="nn-title">TÍTULO</label><input id="nn-title" value={noticeForm.title} onChange={e=>setNoticeForm({...noticeForm,title:e.target.value})} placeholder="Ej. Canilla rota en la cocina"/></div><div className="form-row"><div className="field"><label htmlFor="nn-cat">CATEGORÍA</label><select id="nn-cat" value={noticeForm.category} onChange={e=>setNoticeForm({...noticeForm,category:e.target.value})}><option>Plomería</option><option>Electricidad</option><option>Limpieza</option><option>General</option></select></div><div className="field"><label htmlFor="nn-prio">PRIORIDAD</label><select id="nn-prio" value={noticeForm.priority} onChange={e=>setNoticeForm({...noticeForm,priority:e.target.value})}><option>Baja</option><option>Media</option><option>Alta</option></select></div></div><div className="field"><label htmlFor="nn-desc">DESCRIPCIÓN</label><textarea id="nn-desc" value={noticeForm.description} onChange={e=>setNoticeForm({...noticeForm,description:e.target.value})}/></div><div className="field"><label htmlFor="nn-photo">FOTO (opcional)</label><input id="nn-photo" key={fileKey} type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setNoticeFile(e.target.files?.[0]||null)}/><span className="mini muted">Para que todos vean el detalle (por ejemplo, la canilla rota).</span></div><button className="button pink" disabled={busy==='notice'} onClick={createNotice}>PUBLICAR AVISO</button><p className="mini muted">🔔 Todos los de la residencia reciben una notificación con sonido.</p></div></div></div>}

 {tab==='lavarropas'&&<div className="grid"><div className="card span-4"><h3 className="card-title">🧺 Reservar horario</h3><div className="form"><div className="field"><label htmlFor="l-date">DÍA</label><input id="l-date" type="date" min={todayKey} value={laundryForm.date} onChange={e=>setLaundryForm({...laundryForm,date:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="l-from">DESDE</label><input id="l-from" type="time" value={laundryForm.start_time} onChange={e=>setLaundryForm({...laundryForm,start_time:e.target.value})}/></div><div className="field"><label htmlFor="l-to">HASTA</label><input id="l-to" type="time" value={laundryForm.end_time} onChange={e=>setLaundryForm({...laundryForm,end_time:e.target.value})}/></div></div><button className="button blue" disabled={busy==='laundry'} onClick={reserve}>RESERVAR LAVARROPAS</button></div></div><div className="card span-8"><h3 className="card-title">📅 Próximas reservas</h3>{laundry.map(l=><div className={'notice '+(l.finished?'green':'yellow')} key={l.id}><div className="notice-icon">🧺</div><div className="notice-main"><b>{dateAR(l.date)}</b><div className="mini">{l.start_time.slice(0,5)}–{l.end_time.slice(0,5)} · {l.users?.name||'Habitante'} {l.finished?'· FINALIZADA':''}</div></div>{l.user_id===session.id&&!l.finished&&<><button className="button blue" onClick={()=>setEditingLaundry({...l})}>Modificar</button><button className="button green" onClick={()=>finishLaundry(l)}>Finalizar</button></>}{(l.user_id===session.id||isOwner)&&!l.finished&&<button className="button red" onClick={()=>cancelLaundry(l)}>Cancelar</button>}</div>)}{!laundry.length&&<div className="empty">No hay reservas próximas.</div>}
 {editingLaundry&&<div className="card" style={{marginTop:12}}><h3 className="card-title">✏️ Modificar reserva</h3><div className="form"><div className="field"><label htmlFor="el-date">DÍA</label><input id="el-date" type="date" min={todayKey} value={editingLaundry.date} onChange={e=>setEditingLaundry({...editingLaundry,date:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="el-from">DESDE</label><input id="el-from" type="time" value={editingLaundry.start_time.slice(0,5)} onChange={e=>setEditingLaundry({...editingLaundry,start_time:e.target.value})}/></div><div className="field"><label htmlFor="el-to">HASTA</label><input id="el-to" type="time" value={editingLaundry.end_time.slice(0,5)} onChange={e=>setEditingLaundry({...editingLaundry,end_time:e.target.value})}/></div></div><div style={{display:'flex',gap:8}}><button className="button" onClick={saveLaundry}>GUARDAR</button><button className="button red" onClick={()=>setEditingLaundry(null)}>CANCELAR</button></div></div></div>}</div></div>}

 {tab==='calendario'&&<div className="grid"><div className="card span-12"><div className="card-title"><span>📅 Calendario de la casa</span><div style={{display:'flex',gap:7}}><button className="button blue" aria-label="Mes anterior" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}>←</button><b style={{padding:'10px 6px'}}>{month.toLocaleDateString('es-AR',{month:'long',year:'numeric'})}</b><button className="button blue" aria-label="Mes siguiente" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}>→</button></div></div><div className="calendar"><div className="calendar-head">{['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=><b key={x}>{x}</b>)}</div><div className="calendar-grid">{calendarDays.map((d,i)=>d?<div className="calendar-day" key={i}><b>{d.getDate()}</b>{eventsFor(d).map(e=><div className="calendar-event" key={e.id}>{e.text}</div>)}{localKey(d)===todayKey&&<span className="tag green">HOY</span>}</div>:<div className="calendar-day blank" key={i}/>)}</div></div><div className="navnote">🧺 Reservas del lavarropas · 🙋 visitas · 💰 vencimiento del alquiler.</div></div></div>}

 {tab==='alquiler'&&<div className="grid">{isOwner?<><div className="card span-12"><h3 className="card-title"><span>💰 Pagos del mes</span><span className="tag yellow">Vence: {due?dateAR(due):'—'}</span></h3>{(()=>{const target=rentMeta?.next_due||due;const mName=target?new Date(target+'T12:00:00').toLocaleDateString('es-AR',{month:'long'}):'';const overdueN=new Set(payments.filter(p=>p.overdue).map(p=>p.resident_id)).size;return <div className="remind-bar"><div><b>📢 Avisar a todos que ya pueden pagar {mName}</b><div className="mini muted">Ideal al empezar el mes: les llega a todos los habitantes su monto y el vencimiento ({target?dateAR(target):'—'}), menos a quien ya pagó ese mes. A quien debe meses anteriores se le suma al aviso. El día 1 de cada mes este aviso sale solo.{overdueN?` Ahora hay ${overdueN} con pago vencido.`:''}</div></div><button className="button yellow" disabled={busy==='remind-all'} onClick={remindAll}>📢 Avisar a todos: alquiler de {mName}</button></div>})()}<div className="table-wrap"><table className="table"><thead><tr><th>HABITANTE</th><th>VENCE</th><th>ALQUILER</th><th>SERVICIOS</th><th>TOTAL</th><th>ESTADO</th><th>COMPROBANTE</th><th>ACCIÓN</th></tr></thead><tbody>{currentPayments.map(paymentRow)}</tbody></table></div>{!currentPayments.length&&<div className="empty">No hay habitantes activos.</div>}
 {editingPayment&&<div className="card" style={{marginTop:12,background:'#f3ecff'}}><h3 className="card-title">✏️ Editar cobro de {editingPayment.name} · vence {dateAR(editingPayment.due)}</h3><div className="form"><div className="form-row"><div className="field"><label htmlFor="ep-amount">ALQUILER</label><input id="ep-amount" type="number" min={0} inputMode="decimal" value={editingPayment.amount} onChange={e=>setEditingPayment({...editingPayment,amount:e.target.value})}/></div><div className="field"><label htmlFor="ep-serv">SERVICIOS</label><input id="ep-serv" type="number" min={0} inputMode="decimal" value={editingPayment.services_amount} onChange={e=>setEditingPayment({...editingPayment,services_amount:e.target.value})}/></div></div><div className="mini muted">Total: <b>{money(Number(editingPayment.amount||0)+Number(editingPayment.services_amount||0))}</b>. Un cobro editado a mano ya no se recalcula cuando cambiás precios o servicios.</div><div className="row-actions"><button className="button" disabled={busy==='pay-edit'} onClick={savePayment}>GUARDAR</button>{editingPayment.manual&&<button className="button yellow" onClick={resetPayment}>VOLVER AL CÁLCULO AUTOMÁTICO</button>}<button className="button red" onClick={()=>setEditingPayment(null)}>CANCELAR</button></div></div></div>}
 <div className="grid" style={{marginTop:10}}><div className="card span-4"><div className="big-number">{money(rentMeta?.paid_total||0)}</div><div className="mini">Cobrado este mes</div></div><div className="card span-4"><div className="big-number">{money(rentMeta?.pending_total||0)}</div><div className="mini">Pendiente este mes · {paidCount}/{currentPayments.length} pagos</div></div><div className={'card span-4 '+((rentMeta?.overdue_total||0)>0?'card-alert':'')}><div className="big-number">{money(rentMeta?.overdue_total||0)}</div><div className="mini">Deuda de meses anteriores</div></div></div></div>
 <div className="card span-12 fin-link"><div><b>📒 Registro completo de pagos</b><div className="mini muted">Quién pagó y quién no mes a mes, cobros anulados, ingresos, gastos y ganancia.</div></div><button className="button purple" onClick={()=>go('finanzas')}>Ir a Finanzas →</button></div>
 {overduePayments.length>0&&<div className="card span-12 card-alert"><h3 className="card-title">⚠️ Pagos vencidos de meses anteriores</h3><div className="table-wrap"><table className="table"><thead><tr><th>HABITANTE</th><th>VENCIÓ</th><th>ALQUILER</th><th>SERVICIOS</th><th>TOTAL</th><th>ESTADO</th><th>COMPROBANTE</th><th>ACCIÓN</th></tr></thead><tbody>{overduePayments.map(paymentRow)}</tbody></table></div></div>}
 <div className="span-12"><RentSettingsCard api={api} show={show} onChange={loadRent}/><ChargesEditor api={api} show={show} session={session} onChange={loadRent}/><div className="card" style={{marginTop:12}}><h3 className="card-title">🛏️ Precio del alquiler</h3><p className="mini muted">El precio del alquiler se define en <button className="linklike" onClick={()=>go('habitantes')}>Habitantes → Habitaciones, cupos y precios</button>. Es por persona: si la habitación es compartida, cada habitante paga ese monto.</p></div>
 <div className="card" style={{marginTop:12}}><h3 className="card-title">📢 Enviar notificación a un habitante</h3><div className="form-row"><div className="field"><label htmlFor="nf-user">HABITANTE</label><select id="nf-user" value={notifForm.user_id} onChange={e=>setNotifForm({...notifForm,user_id:e.target.value})}>{users.filter(u=>u.role==='resident'&&u.active).map(u=><option key={u.id} value={u.id}>{u.name} · Hab. {u.room||'—'}</option>)}</select></div><div className="field"><label htmlFor="nf-title">TÍTULO</label><input id="nf-title" value={notifForm.title} onChange={e=>setNotifForm({...notifForm,title:e.target.value})}/></div></div><div className="field"><label htmlFor="nf-msg">MENSAJE</label><textarea id="nf-msg" value={notifForm.message} onChange={e=>setNotifForm({...notifForm,message:e.target.value})} placeholder="Ej. Recordatorio de pago, reunión, aviso importante..."/></div><button className="button pink" disabled={busy==='notif'} onClick={sendNotification}>ENVIAR Y HACER SONAR 🔔</button></div></div></>
 :<div className="card span-12"><h3 className="card-title"><span>💰 Tus pagos</span></h3>{payments.map(p=><div className="card pay-card" key={p.id}><div className={'notice '+(p.paid?'green':p.overdue?'red':'yellow')}><div className="notice-icon">{p.paid?'✅':p.overdue?'⚠️':'💰'}</div><div className="notice-main"><b>{p.paid?'Pagado':p.overdue?'Pago vencido':'Pago pendiente'} · {dateAR(p.due_date)}</b><div className="mini">Total: <b>{money(p.total)}</b></div></div></div><div className="breakdown"><div><span>Alquiler habitación {p.room||'—'}</span><b>{money(p.amount)}</b></div>{(p.services_detail||[]).map(s=><div key={s.name}><span>{s.name}</span><b>{money(s.amount)}</b></div>)}<div className="breakdown-total"><span>Total</span><b>{money(p.total)}</b></div></div>{!p.paid&&(p.reported_at?<div className="notice green"><div className="notice-icon">💸</div><div className="notice-main"><b>Le avisaste al dueño que pagaste</b><div className="mini">{new Date(p.reported_at).toLocaleString('es-AR')} · cuando lo confirme, figura como pagado.</div></div><button className="button yellow" disabled={busy==='report-'+p.id} onClick={()=>reportPaid(p)}>Avisar de nuevo</button></div>:<button className="button pink" style={{width:'100%',marginBottom:10}} disabled={busy==='report-'+p.id} onClick={()=>reportPaid(p)}>💸 YA PAGUÉ · AVISAR AL DUEÑO</button>)}{!p.paid&&<div className="field"><label htmlFor={'proof-'+p.id}>📎 SUBIR COMPROBANTE (JPG, PNG, WEBP o PDF)</label>{p.proof_url&&<div className="notice green">✅ Ya enviaste un comprobante. <a href={p.proof_url} target="_blank" rel="noreferrer" className="button blue">Ver</a></div>}<input id={'proof-'+p.id} type="file" accept="image/png,image/jpeg,image/webp,application/pdf" onChange={e=>uploadProof(e,p)}/></div>}</div>)}{!payments.length&&<div className="empty">No tenés pagos pendientes. 🎉</div>}</div>}{!isOwner&&rentMeta?.history&&<ResidentRentHistory history={rentMeta.history}/>}</div>}

 {tab==='habitantes'&&isOwner&&<div className="grid"><InvitesCard api={api} show={show} session={session} rooms={rooms}/><RoomsEditor api={api} show={show} session={session} rooms={rooms} onChange={async()=>{await Promise.all([loadRooms(),loadRent()])}}/>
 <div className="card span-5"><h3 className="card-title">👥 Crear habitante a mano</h3><p className="mini muted">Para quien no tiene email o prefiere que le armes la cuenta. Si tiene email, mejor mandale una invitación.</p><div className="form"><div className="field"><label htmlFor="u-name">NOMBRE</label><input id="u-name" value={userForm.name} onChange={e=>setUserForm({...userForm,name:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="u-user">USUARIO (si no tiene email)</label><input id="u-user" autoCapitalize="none" value={userForm.username} onChange={e=>setUserForm({...userForm,username:e.target.value.toLowerCase()})}/></div><div className="field"><label htmlFor="u-room">HABITACIÓN</label><select id="u-room" value={userForm.room} onChange={e=>setUserForm({...userForm,room:e.target.value})}><option value="">Elegir...</option>{roomOptions()}</select></div></div><div className="form-row"><div className="field"><label htmlFor="u-mail">CORREO</label><input id="u-mail" type="email" value={userForm.email} onChange={e=>setUserForm({...userForm,email:e.target.value})}/></div><div className="field"><label htmlFor="u-phone">NÚMERO</label><input id="u-phone" type="tel" value={userForm.phone} onChange={e=>setUserForm({...userForm,phone:e.target.value})}/></div></div><div className="field"><label htmlFor="u-em">NÚMERO DE CERCANO / EMERGENCIA</label><input id="u-em" type="tel" value={userForm.emergency_phone} onChange={e=>setUserForm({...userForm,emergency_phone:e.target.value})}/></div><div className="field"><label htmlFor="u-pass">CONTRASEÑA INICIAL</label><input id="u-pass" type="text" autoComplete="new-password" value={userForm.password} onChange={e=>setUserForm({...userForm,password:e.target.value})} placeholder="Mínimo 8 caracteres"/><span className="mini muted">Pasásela al habitante; después la puede cambiar en Mi perfil.</span></div><button className="button purple" disabled={busy==='user'} onClick={createUser}>CREAR USUARIO</button></div></div>
 <div className="card span-7"><h3 className="card-title">🏡 Habitantes por habitación</h3>{roomsGrouped.map(g=><div key={g.id} className="card" style={{marginBottom:10,background:'#fff'}}><h4 style={{margin:'0 0 8px'}}>Habitación {g.number} · {g.people.length}/{g.capacity} {g.capacity===1?'lugar':'lugares'}</h4>{g.people.length?g.people.map(u=><div className="notice green" key={u.id}><div className="notice-icon">🧑</div><div className="notice-main"><b>{u.name}</b><div className="mini muted">{u.role==='admin'&&<span className="tag">Encargado/a</span>} {u.email||'sin correo'} · {u.phone||'sin número'} · cercano: {u.emergency_phone||'—'}</div></div><button className="button blue" onClick={()=>setEditingUser({...u,password:''})}>Modificar</button><button className="button red" onClick={()=>setUserActive(u,false)}>Desactivar</button></div>):<div className="empty">Habitación libre.</div>}</div>)}
 {users.some(u=>u.role==='admin'&&u.active)&&<div className="card" style={{marginBottom:10,background:'#fff'}}><h4 style={{margin:'0 0 8px'}}>🧑‍💼 Encargados</h4>{users.filter(u=>u.role==='admin'&&u.active).map(u=><div className="notice" key={u.id}><div className="notice-icon">🧑‍💼</div><div className="notice-main"><b>{u.name}</b><div className="mini muted">{u.email||'sin correo'} · {u.phone||'sin número'}</div></div>{session.role==='owner'&&<button className="button red" onClick={()=>setUserActive(u,false)}>Quitar</button>}</div>)}</div>}
 {inactive.length>0&&<div className="card" style={{marginBottom:10}}><h4 style={{margin:'0 0 8px'}}>💤 Habitantes desactivados</h4>{inactive.map(u=><div className="notice" key={u.id}><div className="notice-icon">💤</div><div className="notice-main"><b>{u.name}</b><div className="mini muted">@{u.username} · última hab. {u.room||'—'}</div></div><button className="button" onClick={()=>setUserActive(u,true)}>Reactivar</button></div>)}</div>}
 {editingUser&&<div className="card" style={{background:'#f3ecff'}}><h3 className="card-title">✏️ Modificar habitante</h3><div className="form"><div className="field"><label htmlFor="eu-name">NOMBRE</label><input id="eu-name" value={editingUser.name} onChange={e=>setEditingUser({...editingUser,name:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="eu-room">HABITACIÓN</label><select id="eu-room" value={editingUser.room||''} onChange={e=>setEditingUser({...editingUser,room:e.target.value})}>{roomOptions(users.find(u=>u.id===editingUser.id)?.room)}</select></div><div className="field"><label htmlFor="eu-mail">CORREO</label><input id="eu-mail" type="email" value={editingUser.email||''} onChange={e=>setEditingUser({...editingUser,email:e.target.value})}/></div></div><div className="form-row"><div className="field"><label htmlFor="eu-phone">NÚMERO</label><input id="eu-phone" type="tel" value={editingUser.phone||''} onChange={e=>setEditingUser({...editingUser,phone:e.target.value})}/></div><div className="field"><label htmlFor="eu-em">NÚMERO DE CERCANO</label><input id="eu-em" type="tel" value={editingUser.emergency_phone||''} onChange={e=>setEditingUser({...editingUser,emergency_phone:e.target.value})}/></div></div><div className="field"><label htmlFor="eu-pass">NUEVA CONTRASEÑA (opcional)</label><input id="eu-pass" type="text" autoComplete="new-password" value={editingUser.password||''} onChange={e=>setEditingUser({...editingUser,password:e.target.value})} placeholder="Dejala vacía para no cambiarla"/></div><div style={{display:'flex',gap:8}}><button className="button" onClick={saveUser}>GUARDAR</button><button className="button red" onClick={()=>setEditingUser(null)}>CANCELAR</button></div></div></div>}</div></div>}

 {tab==='tareas'&&<TasksSection api={api} show={show} session={session} rooms={rooms}/>}
 {tab==='invitados'&&<GuestsSection api={api} show={show} session={session} upload={(f,k)=>upload(f,k)}/>}
 {tab==='gastos'&&isOwner&&<ExpensesSection api={api} show={show} session={session} defaultEmail={profile?.email}/>}
 {tab==='finanzas'&&isOwner&&<FinanceSection api={api} show={show} session={session} defaultEmail={profile?.login_email||profile?.email}/>}

 {tab==='residencias'&&<HomesSection api={api} show={show} session={session} homes={homes} onSwitch={switchHome}/>}
 {tab==='normas'&&<RulesSection api={api} show={show} session={session}/>}

 {tab==='perfil'&&profile&&<div className="grid"><div className="card span-6"><h3 className="card-title">🧑 Mi perfil</h3><div className="person"><div className="avatar" style={{width:72,height:72,fontSize:30}}>{profile.photo_url?<img src={profile.photo_url} alt="Foto de perfil" style={{width:'100%',height:'100%',objectFit:'cover'}}/>:'🧑'}</div><div><div className="big-number" style={{fontSize:20}}>{profile.name}</div><div className="muted">@{profile.username}</div></div></div><div className="field" style={{marginTop:12}}><label htmlFor="pf-photo">FOTO</label><input id="pf-photo" type="file" accept="image/png,image/jpeg,image/webp" onChange={uploadPhoto}/></div><div className="form" style={{marginTop:12}}><div className="field"><label htmlFor="pf-name">NOMBRE</label><input id="pf-name" value={profileForm.name} onChange={e=>setProfileForm({...profileForm,name:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="pf-mail">EMAIL (para entrar y recuperar la contraseña)</label><input id="pf-mail" type="email" autoComplete="email" value={profileForm.email} onChange={e=>setProfileForm({...profileForm,email:e.target.value})}/></div><div className="field"><label htmlFor="pf-phone">NÚMERO</label><input id="pf-phone" type="tel" autoComplete="tel" value={profileForm.phone} onChange={e=>setProfileForm({...profileForm,phone:e.target.value})}/></div></div><div className="field"><label htmlFor="pf-em">NÚMERO DE CERCANO</label><input id="pf-em" type="tel" value={profileForm.emergency_phone} onChange={e=>setProfileForm({...profileForm,emergency_phone:e.target.value})}/></div><button className="button purple" onClick={saveProfile}>GUARDAR CAMBIOS</button></div></div>
 <div className="card span-6"><h3 className="card-title">📅 Información de residencia</h3><div className="notice green"><div className="notice-icon">🗓️</div><div className="notice-main"><b>En la residencia desde</b><div>{new Date(profile.created_at).toLocaleDateString('es-AR')}</div></div></div>{!isOwner&&<><div className={'notice '+(myUnpaid.length?'yellow':'green')}><div className="notice-icon">💰</div><div className="notice-main"><b>{myUnpaid.some(p=>p.overdue)?'Tenés un pago vencido':myUnpaid.length?'Pago pendiente':'Pago al día ✅'}</b><div className="mini">Próxima fecha de pago: {myUnpaid.length?dateAR(myUnpaid[myUnpaid.length-1].due_date):rentMeta?.next_due?dateAR(rentMeta.next_due):'—'}</div></div></div><div className="notice"><div className="notice-icon">🏠</div><div className="notice-main"><b>Habitación {profile.room||'—'}</b><div className="mini muted">Si necesitás cambiarte de habitación, pedíselo al dueño.</div></div></div></>}
 <h3 className="card-title" style={{marginTop:16}}>🔐 Cambiar contraseña</h3><div className="form"><div className="field"><label htmlFor="pw-cur">CONTRASEÑA ACTUAL</label><input id="pw-cur" type="password" autoComplete="current-password" value={passwordForm.current_password} onChange={e=>setPasswordForm({...passwordForm,current_password:e.target.value})}/></div><div className="form-row"><div className="field"><label htmlFor="pw-new">NUEVA</label><input id="pw-new" type="password" autoComplete="new-password" value={passwordForm.new_password} onChange={e=>setPasswordForm({...passwordForm,new_password:e.target.value})} placeholder="Mínimo 8 caracteres"/></div><div className="field"><label htmlFor="pw-rep">REPETIR NUEVA</label><input id="pw-rep" type="password" autoComplete="new-password" value={passwordForm.confirm} onChange={e=>setPasswordForm({...passwordForm,confirm:e.target.value})}/></div></div><button className="button blue" onClick={changePassword}>CAMBIAR CONTRASEÑA</button></div></div>
 <div className="card span-12"><h3 className="card-title">📲 App y notificaciones</h3><InstallCard/><PushToggle api={api} show={show}/><DeleteAccount api={api} show={show}/><p className="mini muted" style={{marginTop:12}}><a href="/privacidad" target="_blank">Política de privacidad</a> · <a href="/terminos" target="_blank">Términos de uso</a></p></div></div>}

 {tab==='notificaciones'&&<div className="grid"><div className="card span-12"><h3 className="card-title"><span>🔔 Notificaciones</span><span className="row-actions">{unread>0&&<button className="button yellow" onClick={()=>markRead()}>Marcar todas como leídas</button>}{notifications.some(n=>n.read)&&<button className="button red" onClick={()=>confirm('¿Borrar todas las notificaciones que ya leíste?')&&deleteNotif()}>🧹 Borrar leídas</button>}</span></h3>{notifications.map(n=><div className={'notice '+(n.read?'':'yellow')} key={n.id}><button className="notice-open" onClick={()=>!n.read&&markRead(n)} aria-label={n.read?n.title:`Marcar como leída: ${n.title}`}><div className="notice-icon">{notifIcon[n.kind]||'🔔'}</div><div className="notice-main"><div className="notice-title">{n.title}</div><div className="mini muted">{n.message}</div><div className="mini muted">{new Date(n.created_at).toLocaleString('es-AR')}</div></div></button>{n.read?<button className="icon-btn" aria-label={`Borrar: ${n.title}`} title="Borrar" onClick={()=>deleteNotif(n)}>🗑️</button>:<span className="tag yellow">NUEVA</span>}</div>)}<p className="mini muted">Las notificaciones leídas se borran solas a los 60 días.</p>{!notifications.length&&<div className="empty">No tenés notificaciones.</div>}</div></div>}
 </>}</section></main>
 <nav className="mobile-nav" aria-label="Secciones">{['inicio','avisos','alquiler'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>go(t)}><span>{iconMap[t]}</span>{title[t]}</button>)}<button className={tab==='notificaciones'?'active':''} onClick={()=>go('notificaciones')} aria-label={`Notificaciones${unread?`, ${unread} sin leer`:''}`}><span>🔔</span>{unread?<b className="nav-count">{unread}</b>:'Notif.'}</button><button onClick={()=>setMoreOpen(true)} aria-expanded={moreOpen}><span>☰</span>Más</button></nav>
 {moreOpen&&<div className="sheet-backdrop" onClick={()=>setMoreOpen(false)}><div className="sheet" role="dialog" aria-label="Todas las secciones" onClick={e=>e.stopPropagation()}><div className="card-title"><b>Todas las secciones</b><button className="button red" onClick={()=>setMoreOpen(false)} aria-label="Cerrar">✕</button></div><div className="quickgrid">{tabs.map(t=><button key={t} className={'quick '+(tab===t?'purple':'')} onClick={()=>go(t)}><span>{iconMap[t]}</span>{title[t]}</button>)}</div></div></div>}
 {toast&&<div className="toast" role="status">{toast}</div>}</div>
}
